function esc(s) {
  return s.replace(/[<>&"]/g, (ch) => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;' })[ch]);
}

// KML writer: one Placemark per feature. A feature with no position keeps its data and has no geometry.
export function placemark(feature) {
  const data = Object.entries(feature.properties)
    .map(([k, v]) => '<Data name="' + esc(k) + '"><value>' + esc(String(v)) + '</value></Data>')
    .join('');
  const point = feature.geometry?.coordinates;
  const geometry = point ? '<Point><coordinates>' + point[0] + ',' + point[1] + '</coordinates></Point>' : '';
  return '<Placemark><ExtendedData>' + data + '</ExtendedData>' + geometry + '</Placemark>';
}

