import { test } from 'node:test';
import assert from 'node:assert/strict';
import { placemark } from '../src/kml-writer.js';

test('a point is written with its coordinates', () => {
  const kml = placemark({ properties: { name: 'A' }, geometry: { coordinates: [-105.2, 39.7] } });
  assert.match(kml, /<Point><coordinates>-105.2,39.7<\/coordinates><\/Point>/);
});

test('a row with no position keeps its data and writes no NaN', () => {
  const kml = placemark({ properties: { name: 'B' }, geometry: null });
  assert.match(kml, /<value>B<\/value>/);
  assert.doesNotMatch(kml, /NaN|<Point>/);
});
